export type Pattern = {
  slug: string;
  name: string;
  description: string;
  example?: { text: string; verified: boolean };
  /** registry key in src/components/demos/registry.tsx */
  demo?: string;
  /** slug of the pattern whose demo this one shares */
  aliasOf?: string;
};

export type Category = {
  id: string;
  slug: string;
  name: string;
  patterns: Pattern[];
};

